need_upward_RA = self.Non_Crossing_Biased_Climb() and self.Own_Below_Threat() and (self.Cur_Vertical_Sep >= self.MINSEP) and (self.Up_Separation >= self.ALIM())
need_downward_RA = self.Non_Crossing_Biased_Descend() and self.Own_Above_Threat() and (self.Cur_Vertical_Sep >= self.MINSEP) and (self.Down_Separation >= self.ALIM())
if need_upward_RA and need_downward_RA:
    alt_sep = 'UNRESOLVED'
elif need_upward_RA:
    alt_sep = 'UPWARD_RA'
elif need_downward_RA:
    alt_sep = 'DOWNWARD_RA'
else:
    alt_sep = 'UNRESOLVED'
return alt_sep
